package in.kabadiwala.connect.service; import in.kabadiwala.connect.repository.*; import org.apache.pdfbox.pdmodel.*; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.apache.pdfbox.pdmodel.PDPageContentStream; import org.springframework.stereotype.Service; import java.io.*; @Service public class ReceiptService {private final TransactionRepository tx;private final UserRepository users;public ReceiptService(TransactionRepository t,UserRepository u){tx=t;users=u;} public byte[] pdf(String uid,String txid){var t=tx.findAll().stream().filter(x->x.transactionId.equals(txid)).findFirst().orElseThrow(()->new IllegalArgumentException("Transaction not found"));if(!uid.equals(t.collectorId)&&!uid.equals(t.recyclerId))throw new IllegalArgumentException("Access denied");if(!"COMPLETED".equals(t.status))throw new IllegalArgumentException("Receipt available after completion");var c=users.findById(t.collectorId).orElseThrow();var r=users.findById(t.recyclerId).orElseThrow();try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){var page=new PDPage();doc.addPage(page);try(var cs=new PDPageContentStream(doc,page)){var font=new PDType1Font(Standard14Fonts.FontName.HELVETICA);var bold=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);float y=740;String[] lines={"KABADIWALA CONNECT - DIGITAL RECEIPT","Connect | Verify | Recycle","Receipt ID: "+t.receiptId,"Transaction ID: "+t.transactionId,"Lot ID: "+t.lotId,"Collector: "+c.fullName,"Recycler: "+r.fullName,"Material: "+t.material,"Final Weight: "+t.finalWeight+" kg","Final Amount: INR "+String.format("%.2f",t.finalAmount),"Payment Status: "+t.paymentStatus,"Handover Status: "+t.handoverStatus,"Completed: "+t.completedAt};for(int i=0;i<lines.length;i++){cs.beginText();cs.setFont(i==0?bold:font,i==0?18:12);cs.newLineAtOffset(55,y);cs.showText(lines[i]);cs.endText();y-=i<2?30:24;}}doc.save(out);return out.toByteArray();}catch(Exception e){throw new IllegalStateException("Receipt generation failed",e);}}}
